function albumHTML(){S.boards=S.boards||{};var ks=Object.keys(S.boards).filter(alKeep).sort().reverse();if(!ks.length)return "<div class='c'><b>🖼️ Your album</b><p>Nothing here yet. Fill today's board on the Vision tab and it will appear here with its date. Boards save automatically.</p></div>";var h="<div class='c'><b>🖼️ Your album</b><br><small>Every board you make is kept here by date, private on this phone. Tap one to open it.</small></div>",cur='';ks.forEach(function(k){var lbl,d;if(k[0]=='y')lbl='Year visions';else{d=new Date(k.slice(1)+'T00:00:00');lbl=d.toLocaleDateString(undefined,{month:'long',year:'numeric'})}if(lbl!=cur){if(cur)h+="</div>";h+="<div class='alm'>"+lbl+"</div><div class='alg'>";cur=lbl}var A=S.boards[k],n=A.filter(function(i){return i.t=='img'}).length,t=k[0]=='y'?'🌟 '+k.slice(1)+' vision':d.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'})+(k.slice(1)==TK()?' · today':'');h+="<button class='alc' data-k='"+k+"' onclick='alOpen(this.dataset.k)'><div class='alt'>"+alThumb(A)+"</div><b>"+t+"</b><small>"+(n?n+' photo'+(n>1?'s':'')+' · ':'')+A.length+' items</small></button>'});return h+"</div>"}

/* ---- Us: a board two people share ---- */
var us={db:null,uid:null,items:[],state:'idle'};
function usInit(){if(us.state!='idle')return;us.state='load';var T=setTimeout(function(){if(us.state=='load'){us.state='off';usDraw()}},10000);try{if(!(window.claude&&claude.use))throw 0;Promise.all([claude.use('db'),claude.use('user')]).then(function(r){var c=r[0],u=r[1];if(!c){clearTimeout(T);us.state='off';usDraw();return}us.db=c;(u&&u.id?u.id():Promise.resolve(null)).then(function(id){us.uid=id;c.collection('us').onSnapshot(function(s){clearTimeout(T);us.items=s.docs.map(function(d){var o=d.data()||{};o.id=d.id;return o});us.state='on';usDraw()},function(){clearTimeout(T);us.state='off';usDraw()})})}).catch(function(){clearTimeout(T);us.state='off';usDraw()})}catch(e){clearTimeout(T);us.state='off';usDraw()}}
function usAdd(o){if(!us.db)return;us.db.collection('us').add(Object.assign({by:us.uid,ts:Date.now(),day:TK()},o)).then(function(){say('Added to your shared board 💞')}).catch(function(e){say('Could not save: '+((e&&e.message)||'try again'),6000)})}
function usShrink(f,cb){var rd=new FileReader();rd.onload=function(){var im=new Image();im.onload=function(){var q=.62,s=Math.min(1,480/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*s);c.height=Math.round(im.height*s);var x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);var u=c.toDataURL('image/jpeg',q);while(u.length>200000&&q>.3){q-=.1;u=c.toDataURL('image/jpeg',q)}cb(u)};im.src=rd.result};rd.readAsDataURL(f)}
function usPhotos(fs){[].forEach.call(fs,function(f){if(/^image\//.test(f.type))usShrink(f,function(u){usAdd({t:'img',src:u})})})}
function usNote(){var i=$('usn'),v=i.value.trim();if(!v)return;var cs=['#fff3a8','#ffd0e3','#c9f0d8','#cfe4ff','#e5d4ff'];usAdd({t:'note',text:v,c:cs[Math.floor(Math.random()*cs.length)]});i.value=''}
function usDel(id){if(us.db)us.db.doc('us/'+id).delete().catch(function(){})}
function usDraw(){var f=$('usfeed'),bar=$('usbar');if(!f||tab!='us')return;if(us.state=='off'){bar.style.display='none';f.innerHTML="<div class='c'><b>Sharing isn't switched on here</b><p>The shared board needs the published Study Buddy link, opened while signed in to Claude. Ask the owner to share the link with you as an editor/contributor, then open it on your phone. Your own boards stay private either way.</p></div>";return}if(us.state!='on'){bar.style.display='none';f.innerHTML="<div class='c'>Connecting to your shared board…</div>";return}bar.style.display='';var g={};us.items.forEach(function(i){(g[i.day||'?']=g[i.day||'?']||[]).push(i)});g[TK()]=g[TK()]||[];var h='';Object.keys(g).sort().reverse().forEach(function(d){var L=g[d].sort(function(a,b){return (a.ts||0)-(b.ts||0)}),dt=new Date(d+'T00:00:00');h+="<div class='alm'>"+(d==TK()?'Today · ':'')+(isNaN(dt)?d:dt.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short',year:'numeric'}))+"</div>"+(L.length?"<div class='usg'>"+L.map(function(i){var me=i.by&&i.by==us.uid,w=(me?'You':'Partner')+' · '+(i.ts?new Date(i.ts).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):''),x=me?"<button class='x' data-i='"+i.id+"' onclick='usDel(this.dataset.i)'>✕</button>":'';return "<div class='usc'>"+(i.t=='img'?"<img src='"+i.src+"'>":"<p style='background:"+(i.c||'#fff3a8')+"'>"+esc(i.text||'')+"</p>")+"<small>"+w+"</small>"+x+"</div>"}).join('')+"</div>":"<div class='c'><small>Nothing yet today. Add the first moment 💛</small></div>")});f.innerHTML=h}
function usHTML(){return "<div class='c'><b>💞 Our shared board</b><br><small>Both of you can add photos and notes about today. Everything here is visible to both people (your other boards stay private).</small><div id='usbar' class='row' style='margin-top:10px;display:none'><label class='b p' style='cursor:pointer'>📷 Add photos<input type='file' accept='image/*' multiple style='display:none' onchange='usPhotos(this.files);this.value=\"\"'></label><input id='usn' placeholder='What happened today?' style='flex:1;min-width:140px' onkeydown='if(event.key==\"Enter\")usNote()'><button class='b' onclick='usNote()'>Add note</button></div></div><div id='usfeed'></div>"}

var _ex10=extra;extra=function(){var m=$('main');if(tab=='album')m.innerHTML=albumHTML();if(tab=='us')m.innerHTML=usHTML();_ex10();var nv=$('nav'),a=nv.querySelector('[data-t=vis]')||nv.firstElementChild;if(a)a.insertAdjacentHTML('afterend',"<button class='"+(tab=='album'?'on':'')+"' data-t='album' onclick='tab=this.dataset.t;render()'>🖼️ Album</button><button class='"+(tab=='us'?'on':'')+"' data-t='us' onclick='tab=this.dataset.t;render()'>💞 Us</button>");if(tab=='us'){usInit();usDraw()}var on=nv.querySelector('.on');if(on&&on.scrollIntoView)try{on.scrollIntoView({inline:'center',block:'nearest'})}catch(e){}};

